export fn insert_delete_in_array(v: ?[*]const i64,n:usize,output:[*c]u8,capacity:usize)i64{
 if(v==null||n<4||n>260)return -1;const a=v.?;const op=a[0];const len=a[1];const pos=a[2];const element=a[3];if((op!=0 and op!=1)or len<0 or len>256 or n!=@as(usize,@intCast(len))+4 or pos<0)return -1;if((op==0 and pos>len)or(op==1 and pos>=len)or(op==1 and element!=0))return -1;for(0..@intCast(len))|i|{if(a[i+4]<-2147483648 or a[i+4]>2147483647)return -1;}if(op==0 and(element< -2147483648 or element>2147483647))return -1;const outn:usize=@intCast(len)+@as(usize,if(op==0)1 else 0);if(outn*4>capacity or(outn>0 and output==null))return -2;for(0..outn)|i|{const x:i64=if(op==0)(if(i<@as(usize,@intCast(pos)))a[i+4] else if(i==@as(usize,@intCast(pos)))element else a[i+3])else(if(i<@as(usize,@intCast(pos)))a[i+4] else a[i+5]);const w:u32=@bitCast(@as(i32,@intCast(x)));output[i*4]=@truncate(w);output[i*4+1]=@truncate(w>>8);output[i*4+2]=@truncate(w>>16);output[i*4+3]=@truncate(w>>24);}return @intCast(outn*4);
}
